  eV = `Permainan Penuh Jalan Cerita Cemerlang`,
  tV = `Santai Je`,
  nV = `Jangan cadangkan kategori tertentu, sebaliknya biarkan peminat anda memilih kategori yang mereka rasa paling sesuai untuk permainan anda. Acara ini masih akan menyertakan pautan ke halaman pencalonan.`,
  rV = `Tiada Kategori`,
  iV = `Mungkin disebabkan oleh permainan yang mendalam, atau jalan cerita yang memukau... watak-watak yang dicipta dengan teliti, rekaan yang sempurna, atau permainan berbilang pemain yang pasti membakar semangat. Apa pun sebabnya, pemenang Anugerah Game of the Year 2020 adalah sebuah klasik yang tiada tandingan.`,
  aV = `Permainan VR Game of the Year bukan sekadar menyamar sebagai realiti biasa. Permainan ini meningkatkan unsur realiti, memanfaatkan medium VR dan mendorong sempadan alam maya.`,
  oV = `Permainan ini sudah lama dilancarkan. Pasukan pembangun sudah jauh melepasi debut produk kreatif mereka, namun sebagai ibu bapa yang baik, mereka terus memelihara dan menyokong ciptaan mereka. Sehingga hari ini, permainan ini masih menerima kandungan baharu selepas bertahun-tahun lamanya.`,
  sV = `Ada permainan yang tidak sama rasanya jika dimainkan secara solo. Mungkin anda memerlukan rakan untuk memberikan sokongan kepada anda. Mungkin juga anda memerlukan rakan untuk ditikam dari belakang. Walau apa pun pilihan anda, keseronokan menanti mereka yang bermain permainan ini bersama rakan-rakan.`,
  cV = `Gaya visual tidak semestinya ingin meniru kesetiaan grafik dunia nyata (walaupun ini adalah matlamat mulia)... ia menggambarkan penampilan dan perasaan unik yang meresap ke seluruh permainan.`,
  lV = `Pereka permainan ini berada di barisan hadapan dalam eksperimen kreatif, membawa perspektif baharu dan kejutan yang mencabar pemikiran. Permainan ini telah menggembirakan, memberikan inspirasi dan menghiburkan dengan pembaharuan yang belum pernah dimainkan sebelum ini.`,
  uV = `Permainan ini memberikan ganjaran kepada ketabahan dan bukan untuk mereka yang mudah menyerah kalah. Ia adalah permainan paling mencabar yang kami pernah nikmati.`,
  dV = `Wira yang tidak dikenali ini patut diiktiraf untuk skor muzikal yang luar biasa. Ini adalah OST yang TERBAIK SEKALI! `,
  fV = `Ada kalanya, hanya permainan dengan naratif cerita yang mendalam mampu memenuhi kehendak hati dan permainan ini memang memberikan impak. Permainan ini menarik seperti drama bersiri dan dihasilkan dengan sempurna seperti lakon layar TV berprestij. Tahniah — kerana berjaya membuat emosi kami bergelora!`,
  pV = `Permainan ini adalah penawar untuk hari yang sibuk. Ia lancar, menenangkan dan membenarkan segala kebimbangan anda hilang. Permainan ini adalah detik ketenangan anda.`,
  mV = `Tukar pencalonan anda?`,
  hV = `Anda hanya boleh mencalonkan satu permainan untuk setiap kategori dan anda telah mencalonkan %1$s untuk kategori ini. Adakah anda ingin mencalonkan %2$s sebagai ganti?`,
