  xV = `Nampaknya akaun anda adalah terhad. Untuk mengelakkan penyalahgunaan pencalonan, anda perlu berbelanja sebanyak USD$5 di Steam untuk menyertai Anugerah Steam. %1$s untuk maklumat lanjut.`,
