  cH = `Ada kalanya, hanya permainan dengan naratif cerita yang mendalam mampu memenuhi kehendak hati dan permainan ini memang memberikan impak. Permainan ini menarik seperti drama bersiri dan dihasilkan dengan sempurna seperti lakon layar TV berprestij. Tahniah — kerana berjaya membuat emosi kami bergelora!`,
