  uH = `Permainan ini sangat hebat, anda teringin untuk membawanya ke semua tempat. Jadi, anda buat juga! Nasib baik, semua yang menjadikannya begitu seronok apabila bermain di meja anda menjadi lebih baik apabila dimainkan di luar.`,
